    26	    public static CheckoutRequest parse(Map<String, Object> body) {
    27	        if (body == null) {
    28	            body = Map.of();
    29	        }
    30	        Map<?, ?> customer = body.get("customer") instanceof Map<?, ?> m ? m : Map.of();
    31	        List<Item> items = null;
    32	        if (body.get("items") instanceof List<?> list) {
    33	            items = list.stream().map(CheckoutRequest::item).toList();
    34	        }
    35	        return new CheckoutRequest(text(customer.get("cpf")), text(customer.get("email")), items,
    36	                text(body.get("zipCode")), text(body.get("region")), text(body.get("shippingMethod")),
    37	                body.get("coupon") != null, text(body.get("coupon")), text(body.get("paymentMethod")),
    38	                installments(body), text(body.get("clubTier")));
