import org.springframework.transaction.support.TransactionTemplate;

@Service
public class OrderService {

    private static final Duration PAYMENT_WINDOW = Duration.ofHours(48);
    private static final String PAYMENT_OK = "OK";

    private final CheckoutService checkout;
    private final OrderRepository orders;
    private final ProductRepository products;
    private final CustomerRepository customers;
    private final List<OrderLifecycleListener> listeners;
    private final TransactionTemplate tx;
    private final Clock clock;

    public OrderService(CheckoutService checkout, OrderRepository orders, ProductRepository products,
                        CustomerRepository customers, List<OrderLifecycleListener> listeners,
                        TransactionTemplate tx, Clock clock) {
        this.checkout = checkout;
        this.orders = orders;
        this.products = products;
        this.customers = customers;
        this.listeners = listeners;
        this.tx = tx;
        this.clock = clock;
    }

    public OrderSummary summarize(CheckoutRequest request) {
        return checkout.summarize(request);
    }

    public Order register(CheckoutRequest request) {
        // computed before opening the transaction: it may call the carrier
        OrderSummary summary = checkout.summarize(request);
        List<Order.Item> items = request.items().stream()
                .map(i -> new Order.Item(i.sku(), i.quantity())).toList();
        Order order = new Order(UUID.randomUUID().toString(), OrderStatus.AWAITING_PAYMENT,
                clock.instant().truncatedTo(ChronoUnit.SECONDS), summary, items, null);
        customers.createIfAbsent(request.cpf(), request.email());
        return inTransaction(() -> {
            orders.insert(request.cpf(), request.email(), order);
            return order;
        });
    }

    public Order get(String id) {
        return orders.find(id).orElseThrow(OrderService::notFound).order();
    }

    public Order confirmPayment(String id, String transactionId, String paidAt) {
        PaymentResult result = inTransaction(() -> doConfirmPayment(id, transactionId, paidAt));
        if (result.error() != null) {
            throw result.error();
        }
        return result.order();
    }

    public Order ship(String id, String trackingCode) {
        return inTransaction(() -> {
            StoredOrder stored = lock(id);
            if (trackingCode == null || trackingCode.isBlank()) {
    public void recordPaymentOutcome(String orderId, String transactionId, String outcome) {
        jdbc.sql("INSERT INTO payment_events (order_id, transaction_id, outcome) VALUES (:o, :t, :out)")
                .param("o", orderId).param("t", transactionId).param("out", outcome).update();
    }

    private StoredOrder withItems(StoredOrder stored) {
        Order o = stored.order();
        List<Order.Item> items = jdbc.sql("SELECT sku, quantity FROM order_items WHERE order_id = :id ORDER BY position")
                .param("id", o.id()).query((rs, n) -> new Order.Item(rs.getString("sku"), rs.getInt("quantity")))
                .list();
        return new StoredOrder(stored.cpf(), new Order(o.id(), o.status(), o.createdAt(), o.summary(), items,
                o.trackingCode()));
    }

    private StoredOrder map(ResultSet rs, int row) throws SQLException {
        OrderSummary summary = new OrderSummary(money(rs, "products_subtotal"), money(rs, "coupon_discount"),
                money(rs, "shipping_cost"), rs.getInt("delivery_days"), money(rs, "insurance"),
                money(rs, "payment_adjustment"), money(rs, "final_total"), rs.getInt("installments"),
                money(rs, "installment_amount"), money(rs, "next_purchase_credit"), rs.getBoolean("gift"));
        Instant createdAt = rs.getObject("created_at", OffsetDateTime.class).toInstant();
        Order order = new Order(rs.getString("id"), OrderStatus.valueOf(rs.getString("status")), createdAt, summary,
                List.of(), rs.getString("tracking_code"));
        return new StoredOrder(rs.getString("cpf"), order);
    }

    private static java.math.BigDecimal money(ResultSet rs, String column) throws SQLException {
                .query(this::map).optional();
    }

    public void markRead(String id) {
        jdbc.sql("UPDATE notifications SET status = 'READ' WHERE id = :id").param("id", id).update();
    }

    private Notification map(ResultSet rs, int row) throws SQLException {
        return new Notification(rs.getString("id"), NotificationType.valueOf(rs.getString("type")),
                rs.getString("order_id"), rs.getString("status"));
    }
}

